using Starlings.Roost.Generation;

namespace Starlings.Roost.Models.Qwen35.Tests.Parity;

/// <summary>
/// The fixed R-022 prompt set: chat conversations rendered by Starling's <c>Qwen35ChatTemplate</c> (through
/// <see cref="Qwen35RoostChatTemplate"/>) with thinking disabled. Development evidence, not a protected fixture (R-014 proposes
/// those). One prompt is longer than 64 tokens so that transformers' chunked Gated DeltaNet prefill crosses a chunk boundary.
/// </summary>
internal static class R022PromptSet
{
    /// <summary>Greedy tokens generated by the reference per case: 24 tokens make 24 forwards (the prefill and 23 decode steps)
    /// unless the model stops first.</summary>
    public const int MaxNewTokens = 24;

    /// <summary>Thinking stays off: the template closes an empty think block, so the answer starts at once.</summary>
    public const bool EnableThinking = false;

    public static IReadOnlyList<(string Id, RoostChatMessage[] Messages)> Cases { get; } =
    [
        ("capital", [RoostChatMessage.User("Explain in three sentences why Paris became the capital of France.")]),
        ("system-haiku",
        [
            RoostChatMessage.System("You are a concise assistant who answers in plain English."),
            RoostChatMessage.User("Write a haiku about autumn rain, then explain the imagery in one sentence."),
        ]),
        ("multi-turn",
        [
            RoostChatMessage.User("I have 3 apples and buy 5 more. How many do I have?"),
            RoostChatMessage.Assistant("You have 8 apples."),
            RoostChatMessage.User("If I eat two and give half of the rest to a friend, how many are left? Explain step by step."),
        ]),
        ("code", [RoostChatMessage.User("Write a Python function that returns the n-th Fibonacci number iteratively, with a docstring.")]),
        ("long-context",
        [
            RoostChatMessage.User(
                "Read the following note and list its three main points as bullets.\n\n"
                + "The town council met on Tuesday to discuss the new library. The architect presented two designs: a single-storey "
                + "building with a large reading garden, and a three-storey building on a smaller plot that leaves room for a car park. "
                + "Residents who spoke were divided; parents wanted the garden, while shop owners worried about parking on market days. "
                + "The treasurer said the budget covers either design, but the taller building would cost more to heat and maintain. "
                + "The council agreed to hold a public consultation in March and to publish both designs online before then."),
        ]),
    ];

    public static string Render(RoostChatMessage[] messages) => Qwen35RoostChatTemplate.Instance.Render(messages, enableThinking: EnableThinking);
}
